async function persist(next:Journal,saveDemo=false){if(saving||loading)return false;next={...next,tasks:next.tasks.map(t=>t.status==='done'&&descendants(next.tasks,t.id).some(c=>c.status!=='done')?{...t,status:'doing',completedAt:null}:t)};if(demo&&!saveDemo){setData(next);return true}setSaving(true);setError('');try{const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:next,version})});const j=await r.json() as {error?:string;version:number;data?:Journal};if(!r.ok)throw Error(j.error||'Không thể lưu công việc.');setData(j.data||next);setVersion(j.version);setDemo(false);setToast('Đã lưu vào sổ tay cá nhân');return true}catch(e){setError((e as Error).message);return false}finally{setSaving(false)}}
useEffect(()=>{const active=!!(edit||aiOpen||settings||notifications);if(!active)return;const previous=document.body.style.overflow;document.body.style.overflow='hidden';const escape=(e:KeyboardEvent)=>{if(e.key==='Escape'){if(edit)setEdit(null);else if(settings)setSettings(false);else if(notifications)setNotifications(false);else setAiOpen(false)}};window.addEventListener('keydown',escape);return()=>{document.body.style.overflow=previous;window.removeEventListener('keydown',escape)}},[edit,aiOpen,settings,notifications]);
const resources=data.resources||[];
async function saveResources(next:typeof resources){const ids=new Set(next.map(r=>r.id));return persist({...data,resources:next,tasks:data.tasks.map(t=>({...t,resourceIds:t.resourceIds?.filter(id=>ids.has(id))}))})}
const tasks=data.tasks,leaves=tasks.filter(t=>!tasks.some(c=>c.parentId===t.id)),journeys=tasks.filter(t=>tasks.some(c=>c.parentId===t.id)&&!t.parentId),done=leaves.filter(t=>t.status==='done'),pending=leaves.filter(t=>t.status!=='done'),todayTasks=leaves.filter(t=>t.due===today()).sort((a,b)=>a.time.localeCompare(b.time)),overdue=pending.filter(t=>t.due<today()),rate=Math.round(done.length/(leaves.length||1)*100),categories=Array.from(new Set(tasks.map(t=>t.project)));
const filtered=tasks.filter(t=>(!query||(t.title+' '+t.project).toLocaleLowerCase('vi').includes(query.toLocaleLowerCase('vi')))&&(category==='all'||t.project===category)&&(filter==='all'||filter==='today'&&t.due===today()||filter==='overdue'&&t.due<today()&&t.status!=='done'||filter==='root'&&!t.parentId||filter==='child'&&!!t.parentId||t.status===filter));
const monthKey=`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}`;
const calendarMonthTasks=leaves.filter(t=>t.due.startsWith(monthKey));
const calendarDays=Array.from(new Set(calendarMonthTasks.map(t=>t.due))).sort();
const nextUp=pending.filter(t=>t.due>=today()).sort((a,b)=>(a.due+a.time).localeCompare(b.due+b.time));
function moveCalendarMonth(delta:number){const target=new Date(month.getFullYear(),month.getMonth()+delta,1);setMonth(target);setSelectedDay(dateKey(target))}
function openTask(t:Task){setStep('');setEdit(structuredClone(t))}
function newTask(parentId:string|null=null){setStep('');setEdit({...blank(),parentId,project:tasks.find(t=>t.id===parentId)?.project||'Cá nhân'})}
async function toggle(t:Task){const children=descendants(tasks,t.id);if(t.status!=='done'&&children.some(c=>c.status!=='done')){setToast('Hãy hoàn thành các việc nhỏ trước, rồi đánh dấu việc lớn nhé.');return}const updated={...t,status:t.status==='done'?'todo':'done',completedAt:t.status==='done'?null:today()} as Task;const next=tasks.map(x=>x.id===t.id?updated:x);if(t.parentId&&updated.status!=='done'){const ancestorIds=new Set<string>();let p:string|null|undefined=t.parentId;while(p){ancestorIds.add(p);p=tasks.find(x=>x.id===p)?.parentId||null}for(let i=0;i<next.length;i++)if(ancestorIds.has(next[i].id))next[i]={...next[i],status:'doing',completedAt:null}}await persist({...data,tasks:next})}
async function saveTask(e:React.FormEvent){e.preventDefault();if(!edit)return;if(!edit.title.trim())return;const t={...edit,title:edit.title.trim(),project:edit.project.trim()||'Cá nhân'};if(t.status==='done'&&descendants(tasks,t.id).some(c=>c.status!=='done')){setToast('Việc lớn vẫn còn việc nhỏ chưa hoàn thành.');return}const next=tasks.some(x=>x.id===t.id)?tasks.map(x=>x.id===t.id?t:x):[...tasks,t];if(await persist({...data,tasks:next})){setEdit(null);setStep('');if(demo)setToast('Đã cập nhật bản demo · chưa lưu trực tuyến')}}
function addStep(){if(!edit||!step.trim())return;setEdit({...edit,checklist:[...edit.checklist,{id:uid(),text:step.trim(),done:false}]});setStep('')}
function exportIcs(){const u=URL.createObjectURL(new Blob([calendarText(tasks)],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='nhip-viec.ics';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);setToast('Đã xuất lịch .ics. Nhập vào ứng dụng lịch để sử dụng nhắc việc.')}
function exportBackup(){const u=URL.createObjectURL(new Blob([JSON.stringify({exportedAt:new Date().toISOString(),...data},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='nhip-viec-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function changeTheme(t:string){setTheme(t);try{localStorage.setItem('nhipviec-theme-v3',t)}catch{}}
function setBackdrop(enabled:boolean){setWallpaperEnabled(enabled);try{localStorage.setItem('nhipviec-wallpaper',enabled?'on':'off')}catch{}}
async function uploadWallpaper(file:File|undefined){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){setToast('Chọn ảnh JPG, PNG hoặc WebP tối đa 8 MB nhé.');return}try{await new Promise<void>((resolve,reject)=>{const r=indexedDB.open('nhipviec-appearance',1);r.onupgradeneeded=()=>r.result.createObjectStore('preferences');r.onerror=()=>reject(r.error);r.onsuccess=()=>{const db=r.result,tx=db.transaction('preferences','readwrite');tx.objectStore('preferences').put(file,'wallpaper');tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>reject(tx.error)}});setWallpaper(prev=>{if(prev)URL.revokeObjectURL(prev);return URL.createObjectURL(file)});setBackdrop(true);setToast('Đã lưu hình nền trên thiết bị này')}catch{setToast('Không lưu được ảnh. Trình duyệt có thể đang chặn bộ nhớ.')}}
function removeWallpaper(){const r=indexedDB.open('nhipviec-appearance',1);r.onsuccess=()=>{const tx=r.result.transaction('preferences','readwrite');tx.objectStore('preferences').delete('wallpaper');tx.oncomplete=()=>r.result.close()};if(wallpaper)URL.revokeObjectURL(wallpaper);setWallpaper('')}
function askAI(q:string){if(!q.trim()||reportBusy)return;setQuestion('');setReportBusy(true);const lower=q.toLocaleLowerCase('vi');const week=lower.includes('tuần');const start=week?dayOffset(-6):today();const periodTasks=leaves.filter(t=>t.due>=start&&t.due<=today()),completed=leaves.filter(t=>t.status==='done'&&t.completedAt&&t.completedAt>=start&&t.completedAt<=today());let title='',text='',ids:string[]=[];if(/ưu tiên|nên làm|bắt đầu|tập trung/.test(lower)){const picks=[...pending].sort((a,b)=>{const pa=a.priority==='Cao'?0:a.priority==='Vừa'?1:2,pb=b.priority==='Cao'?0:b.priority==='Vừa'?1:2;return a.due.localeCompare(b.due)||pa-pb||a.time.localeCompare(b.time)}).slice(0,3);title='Việc cần ưu tiên';text=picks.length?`Bạn còn ${pending.length} việc chưa hoàn thành, trong đó ${overdue.length} việc đã quá hạn. Mình gợi ý bắt đầu với ${picks.length} việc dưới đây, xếp theo hạn chót rồi mức ưu tiên. Sau mỗi việc, dành một khoảng nghỉ ngắn nhé.`:'Hiện không còn công việc chưa hoàn thành. Bạn có thể dành thời gian nghỉ ngơi hoặc thêm một mục tiêu mới.';ids=picks.map(t=>t.id)}else if(/chia|nhỏ|bước/.test(lower)){title='Biến việc lớn thành những bước nhỏ';text='Mở một hành trình để thêm việc nhỏ có hạn riêng. Với một công việc cụ thể, hãy viết checklist theo 3 bước: chuẩn bị → thực hiện → kiểm tra. Trong trang chi tiết có nút “Gợi ý checklist mẫu” để bạn xem, chỉnh và thêm; mẫu chưa phải kết quả từ mô hình AI.';ids=journeys.slice(0,2).map(t=>t.id)}else if(/báo cáo|tổng|hôm nay|tuần|tiến độ/.test(lower)){title=week?'Báo cáo 7 ngày':'Báo cáo hôm nay';text=`Bạn đã hoàn thành ${completed.length} việc trong ${week?'7 ngày gần nhất':'hôm nay'}. Có ${periodTasks.length} việc mang hạn chót trong khoảng này; ${periodTasks.filter(t=>t.status!=='done').length} việc trong số đó chưa hoàn thành. Hiện có ${overdue.length} việc quá hạn trên toàn bộ sổ tay. Tiến độ chung: ${done.length}/${leaves.length} việc nhỏ hoặc độc lập (${rate}%). Các việc lớn không được cộng thêm để tránh đếm trùng.`;ids=[...completed,...periodTasks.filter(t=>t.status!=='done')].slice(0,5).map(t=>t.id)}else{title='Mình có thể giúp bạn nhìn lại sổ tay';text='Bản demo tổng hợp bằng quy tắc từ dữ liệu công việc, chưa kết nối mô hình AI. Bạn có thể hỏi “Báo cáo hôm nay”, “Tổng kết tuần”, “Nên ưu tiên việc nào?” hoặc “Chia việc thành các bước nhỏ”.';}setTimeout(()=>{setChats(c=>[...c,{id:uid(),question:q,title,text,ids,range:week?shortDate(start)+' – '+shortDate(today()):shortDate(today())}]);setReportBusy(false)},450)}
